create table public.projetos_f8 (id uuid primary key default gen_random_uuid(), nome text not null check (length(nome) between 1 and 200), cliente text not null default '', tipo text not null check (tipo in ('cftv','alarme')), observacoes text not null default '', planta jsonb not null default '{}', updated_at timestamptz not null default now(), created_at timestamptz not null default now()); alter table public.projetos_f8 enable row level security; revoke all on public.projetos_f8 from anon, authenticated; grant select,insert,update,delete on public.projetos_f8 to authenticated; create policy projetos_robledo on public.projetos_f8 for all to authenticated using ((select auth.uid())='922c325a-19c7-45fc-958a-8c7e561a9a73'::uuid and private.usuario_f8_ativo()) with check ((select auth.uid())='922c325a-19c7-45fc-958a-8c7e561a9a73'::uuid and private.usuario_f8_ativo());